session_start();if(empty($_SESSION['usuario_id'])){header('Location: index.php?acceso=cuenta');exit;}require_once __DIR__.'/backend/conexion.php';$id=(int)$_SESSION['usuario_id'];$msg=$_SESSION['pedido_msg']??'';unset($_SESSION['pedido_msg']);if(empty($_SESSION['csrf_pedidos']))$_SESSION['csrf_pedidos']=bin2hex(random_bytes(32));if($_SERVER['REQUEST_METHOD']==='POST'){$nombre=trim($_POST['nombre']??'');$telefono=trim($_POST['telefono']??'');$direccion=trim($_POST['direccion']??'');$distrito=trim($_POST['distrito']??'');$pass=$_POST['password']??'';if($nombre!==''){$q=$pdo->prepare('UPDATE usuarios SET nombre=?,telefono=?,direccion=?,distrito=? WHERE id=?');$q->execute([$nombre,$telefono,$direccion,$distrito,$id]);$_SESSION['usuario_nombre']=$nombre;if($pass!==''){if(strlen($pass)<8)$msg='La nueva contraseña debe tener al menos 8 caracteres.';else{$q=$pdo->prepare('UPDATE usuarios SET password=? WHERE id=?');$q->execute([password_hash($pass,PASSWORD_DEFAULT),$id]);$msg='Perfil y contraseña actualizados.';}}else $msg='Perfil actualizado correctamente.';}}$q=$pdo->prepare('SELECT nombre,email,telefono,direccion,distrito FROM usuarios WHERE id=?');$q->execute([$id]);$u=$q->fetch();$q=$pdo->prepare('SELECT id,total,estado,costo_envio,metodo_pago,comprobante_pago,pago_verificado,creado_en FROM pedidos WHERE usuario_id=? ORDER BY id DESC');$q->execute([$id]);$orders=$q->fetchAll();$products=$pdo->query('SELECT id,nombre FROM productos WHERE activo=1 ORDER BY nombre')->fetchAll();
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Mi cuenta | Mi Store Arequipa</title><style>body{font:15px Arial;background:#f4f6f8;margin:0;color:#222}.top{background:#17191d;color:white;padding:18px 5%}.top a{color:white;margin-right:15px}.wrap{max-width:950px;margin:28px auto;padding:0 18px}.panel{background:white;padding:20px;border-radius:12px;margin:16px 0}label{display:block;margin:10px 0 5px}input,select,button{padding:10px;border:1px solid #ddd;border-radius:7px;width:100%;box-sizing:border-box}button{background:#e53935;color:white;border:0;margin-top:12px;cursor:pointer}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:10px;border-bottom:1px solid #eee}.msg{color:#187a42}@media(max-width:600px){.grid{grid-template-columns:1fr}}</style></head><body><header class="top"><b>Mi Store Arequipa · Mi cuenta</b>　<a href="index.php">Tienda</a><a href="backend/logout.php">Cerrar sesión</a></header><main class="wrap"><h1>Mi perfil</h1><?php if($msg):?><p class="msg"><?=htmlspecialchars($msg)?></p><?php endif?><section class="panel"><form method="post"><div class="grid"><div><label>Nombre completo</label><input name="nombre" required value="<?=htmlspecialchars($u['nombre'])?>"></div><div><label>Correo (no editable)</label><input disabled value="<?=htmlspecialchars($u['email'])?>"></div><div><label>Teléfono</label><input name="telefono" value="<?=htmlspecialchars($u['telefono']??'')?>"></div><div><label>Distrito</label><input name="distrito" value="<?=htmlspecialchars($u['distrito']??'')?>"></div></div><label>Dirección</label><input name="direccion" value="<?=htmlspecialchars($u['direccion']??'')?>"><label>Nueva contraseña (opcional)</label><input type="password" name="password" minlength="8" placeholder="Dejar vacío para no cambiar"><button>Guardar cambios</button></form></section><section class="panel"><h2>Mis pedidos</h2><table><tr><th>N.º</th><th>Fecha</th><th>Total</th><th>Estado</th><th>Pago</th><th>Comprobante</th><th>Acción</th></tr><?php foreach($orders as $o): $estadoPedido=trim((string)($o['estado']??''));if($estadoPedido===''){$estadoPedido=((float)($o['costo_envio']??0)<=0)?'pendiente_cotizacion_envio':'pendiente';} $etiquetasEstado=['pendiente'=>'Pendiente','pendiente_cotizacion_envio'=>'Envío por cotizar','confirmado'=>'Confirmado','preparando'=>'Preparando','enviado'=>'Enviado','entregado'=>'Entregado','cancelado'=>'Cancelado']; $estadoVisible=$etiquetasEstado[$estadoPedido]??ucfirst(str_replace('_',' ',$estadoPedido)); ?><tr><td>#<?=$o['id']?></td><td><?=$o['creado_en']?></td><td>S/ <?=number_format($o['total'],2)?></td><td><strong><?=htmlspecialchars($estadoVisible)?></strong><?php if($estadoPedido==='pendiente_cotizacion_envio'):?><br><small>Estamos coordinando el costo de entrega.</small><?php endif?></td><td><?=$o['pago_verificado']?'Verificado':'Pendiente de revisión'?></td><td><?php if($o['comprobante_pago']):?><a href="<?=htmlspecialchars($o['comprobante_pago'])?>" target="_blank">Ver</a><?php elseif(stripos($o['metodo_pago'],'contra entrega')===false&&stripos($o['metodo_pago'],'efectivo')===false):?><form action="backend/subir_comprobante.php" method="post" enctype="multipart/form-data"><input type="hidden" name="pedido_id" value="<?=$o['id']?>"><input type="file" name="comprobante" accept="image/jpeg,image/png,image/webp,application/pdf" required><button>Subir</button></form><?php else:?>No aplica<?php endif?></td><td><?php if(in_array($estadoPedido,['','pendiente','pendiente_cotizacion_envio','cancelado'],true)):?><form method="post" action="backend/eliminar_pedido.php" onsubmit="return confirm('¿Eliminar este pedido de tu cuenta?')"><input type="hidden" name="pedido_id" value="<?=$o['id']?>"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars($_SESSION['csrf_pedidos'])?>"><button type="submit">🗑 Borrar</button></form><?php else:?><small>No disponible</small><?php endif?></td></tr><?php endforeach?></table></section><section class="panel"><h2>Escribir una reseña</h2><form action="backend/crear_resena.php" method="post"><label>Producto</label><select name="producto_id" required><?php foreach($products as $p):?><option value="<?=$p['id']?>"><?=htmlspecialchars($p['nombre'])?></option><?php endforeach?></select><label>Calificación</label><select name="calificacion"><option value="5">5 estrellas</option><option value="4">4 estrellas</option><option value="3">3 estrellas</option><option value="2">2 estrellas</option><option value="1">1 estrella</option></select><label>Comentario</label><input name="comentario" maxlength="1000"><button>Enviar para revisión</button></form></section></main></body></html>
